/**
 * HAR 1.2 export from Atlas / network hops — open in Chrome, Proxyman, Charles.
 * @see https://w3c.github.io/web-performance/specs/HAR/Overview.html
 */
import type { NetworkEvent } from './network-event-types';
export interface HarHeader {
    name: string;
    value: string;
}
export interface HarContent {
    size: number;
    mimeType: string;
    text?: string;
    encoding?: string;
}
export interface HarPostData {
    mimeType: string;
    text?: string;
}
export interface HarRequest {
    method: string;
    url: string;
    httpVersion: string;
    cookies: unknown[];
    headers: HarHeader[];
    queryString: Array<{
        name: string;
        value: string;
    }>;
    headersSize: number;
    bodySize: number;
    postData?: HarPostData;
}
export interface HarResponse {
    status: number;
    statusText: string;
    httpVersion: string;
    cookies: unknown[];
    headers: HarHeader[];
    content: HarContent;
    redirectURL: string;
    headersSize: number;
    bodySize: number;
}
export interface HarTimings {
    send: number;
    wait: number;
    receive: number;
    blocked?: number;
    dns?: number;
    connect?: number;
    ssl?: number;
}
export interface HarEntry {
    startedDateTime: string;
    time: number;
    request: HarRequest;
    response: HarResponse;
    cache: Record<string, unknown>;
    timings: HarTimings;
    serverIPAddress?: string;
    connection?: string;
    comment?: string;
}
export interface HarLog {
    version: string;
    creator: {
        name: string;
        version: string;
        comment?: string;
    };
    pages?: unknown[];
    entries: HarEntry[];
    comment?: string;
}
export interface HarDocument {
    log: HarLog;
}
export interface BuildAtlasHarOptions {
    scenario?: string;
    creatorVersion?: string;
    /** Include incident / non-HTTP rows (default false). */
    includeIncidents?: boolean;
}
/** Convert one network hop into a HAR entry. */
export declare function networkEventToHarEntry(ev: NetworkEvent): HarEntry;
/** Build a HAR 1.2 document from network events. */
export declare function buildAtlasHarDocument(networkEvents: readonly NetworkEvent[], options?: BuildAtlasHarOptions): HarDocument;
/** Pretty-printed HAR JSON string. */
export declare function buildAtlasHarJson(networkEvents: readonly NetworkEvent[], options?: BuildAtlasHarOptions): string;
